import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image.D0hFsBgX.png",g=JSON.parse('{"title":"Windows with Caddy","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guidelines/getting-started/windows-with-caddy.md","filePath":"installation-guidelines/getting-started/windows-with-caddy.md"}'),o={name:"installation-guidelines/getting-started/windows-with-caddy.md"};function l(d,a,r,p,h,c){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="windows-with-caddy" tabindex="-1">Windows with Caddy <a class="header-anchor" href="#windows-with-caddy" aria-label="Permalink to &quot;Windows with Caddy&quot;">​</a></h1><h2 id="setting-up-https-for-tradeboard-on-windows-with-caddy" tabindex="-1">Setting Up HTTPS for Tradeboard on Windows with Caddy <a class="header-anchor" href="#setting-up-https-for-tradeboard-on-windows-with-caddy" aria-label="Permalink to &quot;Setting Up HTTPS for Tradeboard on Windows with Caddy&quot;">​</a></h2><p>Run Tradeboard locally on <code>https://tradeboard.local</code> with a valid SSL certificate, no browser warnings, and zero changes to <code>app.py</code>.</p><figure><img src="'+n+`" alt=""><figcaption></figcaption></figure><h3 id="why-this-setup" tabindex="-1">Why this setup? <a class="header-anchor" href="#why-this-setup" aria-label="Permalink to &quot;Why this setup?&quot;">​</a></h3><p>OAuth flows for brokers like shoonya,hdfcsky often require HTTPS redirect URLs. Running Tradeboard on plain <code>http://127.0.0.1:5000</code> works for testing, but production-like local development needs:</p><ul><li>A proper hostname (<code>tradeboard.local</code> instead of <code>127.0.0.1</code>)</li><li>HTTPS with a trusted certificate (no <code>Not Secure</code> warnings)</li><li>No code changes to Tradeboard itself</li></ul><p>Caddy handles all of this in front of your Flask app as a reverse proxy.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Windows 10 or 11</li><li>Tradeboard already cloned and running locally</li><li>Administrator access for two one-time setup steps (hosts file edit, certificate trust)</li></ul><h3 id="step-1-download-caddy" tabindex="-1">Step 1: Download Caddy <a class="header-anchor" href="#step-1-download-caddy" aria-label="Permalink to &quot;Step 1: Download Caddy&quot;">​</a></h3><p>Go to <a href="https://caddyserver.com/download" target="_blank" rel="noreferrer">https://caddyserver.com/download</a></p><p>Select:</p><ul><li><strong>Platform:</strong> Windows</li><li><strong>Architecture:</strong> amd64</li></ul><p>Click <strong>Download</strong>. You&#39;ll get a file named something like <code>caddy_windows_amd64_custom.exe</code>.</p><h3 id="step-2-place-and-rename-the-binary" tabindex="-1">Step 2: Place and rename the binary <a class="header-anchor" href="#step-2-place-and-rename-the-binary" aria-label="Permalink to &quot;Step 2: Place and rename the binary&quot;">​</a></h3><p>Create a folder to hold Caddy:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mkdir C:\\caddy</span></span></code></pre></div><p>Move the downloaded file into <code>C:\\caddy\\</code> and rename it to <code>caddy.exe</code>.</p><p>In PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd C:\\caddy</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Rename-Item</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> caddy_windows_amd64.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> caddy.exe</span></span></code></pre></div><p>Verify it works:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">caddy.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> version</span></span></code></pre></div><p>You should see something like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v2.11.2 h1:iOlpsSiSKqEW+SIXrcZsZ/NO74SzB/ycqqvAIEfIm64=</span></span></code></pre></div><h4 id="tip-show-file-extensions-in-windows" tabindex="-1">Tip: Show file extensions in Windows <a class="header-anchor" href="#tip-show-file-extensions-in-windows" aria-label="Permalink to &quot;Tip: Show file extensions in Windows&quot;">​</a></h4><p>If you see <code>caddy.exe.exe</code> after renaming, Windows is hiding extensions. Open File Explorer, click <strong>View &gt; Show &gt; File name extensions</strong>, then rename again.</p><h3 id="step-3-edit-the-hosts-file" tabindex="-1">Step 3: Edit the hosts file <a class="header-anchor" href="#step-3-edit-the-hosts-file" aria-label="Permalink to &quot;Step 3: Edit the hosts file&quot;">​</a></h3><p>This maps <code>tradeboard.local</code> to your local machine.</p><ol><li>Press the Windows key, type <strong>Notepad</strong></li><li>Right-click Notepad and select <strong>Run as administrator</strong></li><li>In Notepad: <strong>File &gt; Open</strong></li><li>Navigate to: <code>C:\\Windows\\System32\\drivers\\etc\\</code></li><li>Change the file type dropdown (bottom right) from <code>Text Documents (*.txt)</code> to <code>All Files</code></li><li>Open <code>hosts</code></li></ol><p>Add this line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>127.0.0.1    tradeboard.local</span></span></code></pre></div><p>A typical hosts file will look like this after editing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># localhost name resolution is handled within DNS itself.</span></span>
<span class="line"><span>#	127.0.0.1       localhost</span></span>
<span class="line"><span>#	::1             localhost</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Added by Docker Desktop</span></span>
<span class="line"><span>192.168.1.6 host.docker.internal</span></span>
<span class="line"><span>192.168.1.6 gateway.docker.internal</span></span>
<span class="line"><span></span></span>
<span class="line"><span># To allow the same kube context to work on the host and the container:</span></span>
<span class="line"><span>127.0.0.1 kubernetes.docker.internal</span></span>
<span class="line"><span>127.0.0.1 tradeboard.local</span></span>
<span class="line"><span># End of section</span></span></code></pre></div><p>Save and close.</p><p><strong>Verify the entry works:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ping tradeboard.local</span></span></code></pre></div><p>You should see replies from <code>127.0.0.1</code>. If you see <code>could not find host</code>, the hosts file did not save correctly. Reopen Notepad as Administrator and try again.</p><h3 id="step-4-create-the-caddyfile" tabindex="-1">Step 4: Create the Caddyfile <a class="header-anchor" href="#step-4-create-the-caddyfile" aria-label="Permalink to &quot;Step 4: Create the Caddyfile&quot;">​</a></h3><p>Tradeboard ships with a default <code>Caddyfile</code> in the project root. If yours is missing, create it.</p><p>Navigate to your Tradeboard project folder:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd D:\\tradeboard</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">remote\\tradeboard</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">notepad Caddyfile</span></span></code></pre></div><p>When Notepad asks if you want to create the file, click <strong>Yes</strong>. Paste this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tradeboard.local {</span></span>
<span class="line"><span>    reverse_proxy localhost:5000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Save and close.</p><h4 id="note-on-the-caddyfile-name" tabindex="-1">Note on the Caddyfile name <a class="header-anchor" href="#note-on-the-caddyfile-name" aria-label="Permalink to &quot;Note on the Caddyfile name&quot;">​</a></h4><p>The file must be named exactly <code>Caddyfile</code> with no extension. If Notepad saves it as <code>Caddyfile.txt</code>, rename it:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Rename-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Caddyfile.txt Caddyfile</span></span></code></pre></div><h3 id="step-5-run-caddy-for-the-first-time-administrator" tabindex="-1">Step 5: Run Caddy for the first time (Administrator) <a class="header-anchor" href="#step-5-run-caddy-for-the-first-time-administrator" aria-label="Permalink to &quot;Step 5: Run Caddy for the first time (Administrator)&quot;">​</a></h3><p>The first run installs Caddy&#39;s local certificate authority into Windows so browsers trust the auto-generated SSL certificate.</p><ol><li>Press Windows key, type <strong>PowerShell</strong></li><li>Right-click <strong>Windows PowerShell</strong> and select <strong>Run as administrator</strong></li><li>Run these commands:</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd D:\\tradeboard</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">remote\\tradeboard</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\caddy\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">caddy.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run</span></span></code></pre></div><p>Windows will show a security dialog asking permission to install a root certificate. Click <strong>Yes</strong>.</p><p>You should see logs like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INFO    using adjacent Caddyfile</span></span>
<span class="line"><span>INFO    adapted config to JSON</span></span>
<span class="line"><span>INFO    http.auto_https enabling automatic HTTP-&gt;HTTPS redirects</span></span>
<span class="line"><span>INFO    serving initial configuration</span></span></code></pre></div><p>Leave this terminal open. Caddy is now running.</p><h3 id="step-6-start-tradeboard-in-a-separate-terminal" tabindex="-1">Step 6: Start Tradeboard in a separate terminal <a class="header-anchor" href="#step-6-start-tradeboard-in-a-separate-terminal" aria-label="Permalink to &quot;Step 6: Start Tradeboard in a separate terminal&quot;">​</a></h3><p>Open another PowerShell window (no admin needed). Navigate to the project folder and start Tradeboard:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd D:\\tradeboard</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">remote\\tradeboard</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uv run app.py</span></span></code></pre></div><p>You should see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>╭─── Tradeboard v2.0.2.2 ──────────────────────────────╮</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>│        Your Personal Algo Trading Platform         │</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>│ Endpoints                                          │</span></span>
<span class="line"><span>│ Web App    http://127.0.0.1:5000                   │</span></span>
<span class="line"><span>│ WebSocket  ws://127.0.0.1:8765                     │</span></span>
<span class="line"><span>│ Docs       https://docs.algo.wesoftcorp.com                │</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>│ Status     Ready                                   │</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>╰────────────────────────────────────────────────────╯</span></span></code></pre></div><h3 id="step-7-open-tradeboard-in-your-browser" tabindex="-1">Step 7: Open Tradeboard in your browser <a class="header-anchor" href="#step-7-open-tradeboard-in-your-browser" aria-label="Permalink to &quot;Step 7: Open Tradeboard in your browser&quot;">​</a></h3><p>Go to: <strong><a href="https://tradeboard.local" target="_blank" rel="noreferrer">https://tradeboard.local</a></strong></p><p>You should see the Tradeboard login screen with a valid lock icon next to the URL. No certificate warnings.</p><h3 id="step-8-update-broker-callback-urls" tabindex="-1">Step 8: Update broker callback URLs <a class="header-anchor" href="#step-8-update-broker-callback-urls" aria-label="Permalink to &quot;Step 8: Update broker callback URLs&quot;">​</a></h3><p>Now that Tradeboard runs on HTTPS, update the redirect URL in your <code>.env</code> file:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REDIRECT_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://tradeboard.local/shoonya/callback&#39;</span></span></code></pre></div><p>Match this exactly in your broker&#39;s developer console:</p><ul><li><strong>Shoonya API Portal:</strong> Edit your app and set the Redirect URL to <code>https://tradeboard.local/shoonya/callback</code></li></ul><p>Restart Tradeboard after editing <code>.env</code>.</p><p>All the brokers the procedure remains the same.</p><h3 id="daily-workflow-after-setup" tabindex="-1">Daily workflow after setup <a class="header-anchor" href="#daily-workflow-after-setup" aria-label="Permalink to &quot;Daily workflow after setup&quot;">​</a></h3><p>Once everything is set up, your daily workflow is just two terminals:<br><br> Run this from the tradeboard root folder</p><p><strong>Terminal 1 (Caddy):</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\caddy\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">caddy.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run</span></span></code></pre></div><p><strong>Terminal 2 (Tradeboard):</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uv run app.py</span></span></code></pre></div><p>Press <code>Ctrl+C</code> in either terminal to stop. Nothing runs in the background as a service.</p><h3 id="optional-single-command-launcher" tabindex="-1">Optional: Single-command launcher <a class="header-anchor" href="#optional-single-command-launcher" aria-label="Permalink to &quot;Optional: Single-command launcher&quot;">​</a></h3><p>Create <code>start.bat</code> in your Tradeboard folder:</p><div class="language-batch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Caddy&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /k C:\\caddy\\caddy.exe run</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Tradeboard&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /k uv run app.py</span></span></code></pre></div><p>Double-click to launch both. Close both terminal windows when done.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h4 id="browser-shows-err-connection-refused" tabindex="-1">Browser shows ERR_CONNECTION_REFUSED <a class="header-anchor" href="#browser-shows-err-connection-refused" aria-label="Permalink to &quot;Browser shows ERR\\_CONNECTION\\_REFUSED&quot;">​</a></h4><p>Make sure both terminals are running. Caddy must be running for HTTPS to work, and Tradeboard must be running for Caddy to have something to proxy to.</p><h4 id="certificate-warning-in-browser" tabindex="-1">Certificate warning in browser <a class="header-anchor" href="#certificate-warning-in-browser" aria-label="Permalink to &quot;Certificate warning in browser&quot;">​</a></h4><p>This means Caddy&#39;s root CA is not trusted. Stop Caddy, then run as Administrator:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\caddy\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">caddy.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> trust</span></span></code></pre></div><p>Accept the Windows prompt. Restart Caddy.</p><h4 id="port-443-already-in-use" tabindex="-1">Port 443 already in use <a class="header-anchor" href="#port-443-already-in-use" aria-label="Permalink to &quot;Port 443 already in use&quot;">​</a></h4><p>Another service is using the HTTPS port. Common culprits:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">netstat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ano </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> findstr :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span></span></code></pre></div><p>If IIS or <code>World Wide Web Publishing Service</code> is using it, stop the service. Or change Caddy to use a different port:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tradeboard.local:8443 {</span></span>
<span class="line"><span>    reverse_proxy localhost:5000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Then access Tradeboard at <code>https://tradeboard.local:8443</code>.</p><h4 id="caddy-says-caddyfile-input-is-not-formatted" tabindex="-1">Caddy says &quot;Caddyfile input is not formatted&quot; <a class="header-anchor" href="#caddy-says-caddyfile-input-is-not-formatted" aria-label="Permalink to &quot;Caddy says &quot;Caddyfile input is not formatted&quot;&quot;">​</a></h4><p>Cosmetic warning only. To fix, run:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\caddy\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">caddy.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fmt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">overwrite Caddyfile</span></span></code></pre></div><h4 id="hosts-file-ping-does-not-resolve" tabindex="-1">Hosts file ping does not resolve <a class="header-anchor" href="#hosts-file-ping-does-not-resolve" aria-label="Permalink to &quot;Hosts file ping does not resolve&quot;">​</a></h4><p>The most common cause is saving <code>hosts</code> as <code>hosts.txt</code>. Open <code>C:\\Windows\\System32\\drivers\\etc\\</code> in File Explorer with extensions visible (View &gt; Show &gt; File name extensions). If you see <code>hosts.txt</code>, delete it and edit the original <code>hosts</code> file again.</p><h3 id="removing-the-setup" tabindex="-1">Removing the setup <a class="header-anchor" href="#removing-the-setup" aria-label="Permalink to &quot;Removing the setup&quot;">​</a></h3><p>If you want to undo everything:</p><ol><li>Stop Caddy and Tradeboard</li><li>Untrust the Caddy CA: <code>C:\\caddy\\caddy.exe untrust</code> (as Administrator)</li><li>Remove the <code>127.0.0.1 tradeboard.local</code> line from <code>C:\\Windows\\System32\\drivers\\etc\\hosts</code></li><li>Delete <code>C:\\caddy\\</code></li><li>Delete the <code>Caddyfile</code> from your Tradeboard folder</li></ol><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>You now have Tradeboard running on <code>https://tradeboard.local</code> with a fully trusted SSL certificate. No background services, no code changes to Tradeboard, and OAuth callbacks work cleanly with broker APIs that require HTTPS redirect URLs.</p>`,105)])])}const k=e(o,[["render",l]]);export{g as __pageData,k as default};
